#include <cstdio>
#include <cstring>
#include <cmath>
#include <cstdlib>
#include <vector>
#include <string>
#include <algorithm>
#include <queue>
#include <stack>
#include <deque>
#include <map>
#include <set>
#include <unordered_map>
#include <unordered_set>
#include <functional>
#include <numeric>
#include <sstream>
#include <iostream>
using namespace std;
int main(){string s;cin>>s;int n=s.size();
long long cnt=0;
for(int c=0;c<2*n-1;++c){
int l=c/2,r=l+c%2;
while(l>=0&&r<n&&s[l]==s[r]){++cnt;--l;++r;}}
printf("%lld\n",cnt);return 0;}

